Here is the commit message:
net/x25: Fix overflow when accumulating packets

Add a check to ensure that `x25_sock.fraglen` does not overflow.

The `fraglen` also needs to be resetted when purging `fragment_queue` in
`x25_clear_queues()`.

Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Suggested-by: Yiming Qian <yimingqian591@gmail.com>
Signed-off-by: Martin Schiller <ms@dev.tdt.de>
Link: https://patch.msgid.link/20260331-x25_fraglen-v4-2-3e69f18464b4@dev.tdt.de
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The `fraglen` field in `struct x25_sock` is accumulated without any overflow check when receiving packets with the `more` flag set in `x25_queue_rx_frame()`. This can lead to integer overflow if many packets are queued, potentially causing incorrect behavior or security issues. Additionally, when the fragment queue is cleared, the counter is not reset, leading to stale values.

Here is the patch:

 static int x25_queue_rx_frame(struct sock *sk, struct sk_buff *skb, int more)
 {
 	struct sk_buff *skbo, *skbn = skb;
 	struct x25_sock *x25 = x25_sk(sk);

+	/* make sure we don't overflow */
+	if (x25->fraglen + skb->len > USHRT_MAX)
+		return 1;
+
 	if (more) {
 		x25->fraglen += skb->len;
 		skb_queue_tail(&x25->fragment_queue, skb);
 		skb_set_owner_r(skb, sk);
 		return 0;
 	}

 	if (x25->fraglen > 0) {	/* End of fragment */
 		int len = x25->fraglen + skb->len;

 		skbn = alloc_skb(len, GFP_ATOMIC);
 		if (!skbn)
 			return 1;

 		skb_queue_tail(&x25->fragment_queue, skb);

 		skb_reset_transport_header(skbn);

 		skbo = skb_dequeue(&x25->fragment_queue);
 		skb_copy_from_linear_data(skbo, skb_put(skbn, skbo->len),
 					  skbo->len);
 		kfree_skb(skbo);

 		while ((skbo =
 			skb_dequeue(&x25->fragment_queue)) != NULL) {
 			skb_pull(skbo, (x25->neighbour->extended) ?
 					X25_EXT_MIN_LEN : X25_STD_MIN_LEN);
 			skb_copy_from_linear_data(skbo,
 						  skb_put(skbn, skbo->len),
 						  skbo->len);
 			kfree_skb(skbo);
 		}

 		x25->fraglen = 0;
 	}

 	skb_set_owner_r(skbn, sk);
 	skb_queue_tail(&sk->sk_receive_queue, skbn);
 	if (!sock_flag(sk, SOCK_DEAD))
 		sk->sk_data_ready(sk);

 	return 0;
 }



